import React from "react";
import { AbsoluteFill, Img, useCurrentFrame, interpolate, Easing } from "remotion";
import { COLORS, FONTS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

const CLAMP = { extrapolateLeft: "clamp", extrapolateRight: "clamp" } as const;

const SplitSlideDuo: React.FC<PrimitiveProps> = ({ anim, fps, frame: box }) => {
  const frame = useCurrentFrame();
  const W = box.width;
  const H = box.height;
  const dur = Math.max(2, Math.round((anim.end - anim.start) * fps));
  const fast = Math.max(2, Math.round(0.45 * fps));
  const delay = Math.round(0.12 * fps);
  const fadeF = Math.max(1, Math.min(Math.round(0.25 * fps), Math.floor(dur / 3)));

  const src = String(anim.params?.src ?? "");
  const src2 = String(anim.params?.src2 ?? "") || src;
  const text = String(anim.text ?? "").trim();

  // Diagonal seam rising to the right (~11°), kept inside the frame on wide boxes.
  const rise = Math.min(W * 0.097, H * 0.12);
  const gap = Math.max(6, Math.min(W, H) * 0.014);
  const yL = H / 2 + rise;
  const yR = H / 2 - rise;

  // Fast entrance, then a slow continuous drift in the same direction.
  const slide = (f: number, dir: 1 | -1) =>
    dir *
    (interpolate(f, [0, fast], [-W * 1.15, 0], { ...CLAMP, easing: Easing.out(Easing.cubic) }) +
      interpolate(f, [0, dur], [-W * 0.05, W * 0.05], CLAMP));

  const topX = slide(frame, 1);
  const bottomX = slide(frame - delay, -1);
  const seamReveal = interpolate(frame, [fast * 0.6, fast + delay], [0, 1], { ...CLAMP, easing: Easing.out(Easing.cubic) });
  const fadeOut = interpolate(frame, [dur - fadeF, dur], [1, 0], CLAMP);
  const captionIn = interpolate(frame, [fast + delay, fast + delay + Math.round(0.3 * fps)], [0, 1], { ...CLAMP, easing: Easing.out(Easing.back(1.6)) });

  const topClip = `polygon(0px 0px, ${W}px 0px, ${W}px ${yR - gap / 2}px, 0px ${yL - gap / 2}px)`;
  const bottomClip = `polygon(0px ${yL + gap / 2}px, ${W}px ${yR + gap / 2}px, ${W}px ${H}px, 0px ${H}px)`;
  const seamW = W * seamReveal;
  const seamClip = `polygon(0px ${yL - gap / 2}px, ${seamW}px ${yL - gap / 2 - (yL - yR) * seamReveal}px, ${seamW}px ${yL + gap / 2 - (yL - yR) * seamReveal}px, 0px ${yL + gap / 2}px)`;

  const panel = (url: string, x: number, top: number, height: number, pos: string) => (
    <div style={{ position: "absolute", left: -W * 0.07, top, width: W * 1.14, height, translate: `${x}px 0px` }}>
      {url ? (
        <Img src={url} style={{ width: "100%", height: "100%", objectFit: "cover", objectPosition: pos }} />
      ) : (
        <div style={{ width: "100%", height: "100%", background: "rgba(255,255,255,0.08)" }} />
      )}
    </div>
  );

  const fontSize = Math.min(W, H) * (text.length > 24 ? 0.045 : 0.06);

  return (
    <AbsoluteFill style={{ fontFamily: FONTS.display, opacity: fadeOut }}>
      <AbsoluteFill style={{ clipPath: topClip }}>{panel(src, topX, 0, yL, "center 40%")}</AbsoluteFill>
      <AbsoluteFill style={{ clipPath: bottomClip }}>{panel(src2, bottomX, yR, H - yR, src2 === src ? "center 75%" : "center")}</AbsoluteFill>
      <AbsoluteFill style={{ clipPath: seamClip, background: COLORS.teal }} />
      {text ? (
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
          <div
            style={{
              maxWidth: W * 0.8,
              padding: `${fontSize * 0.35}px ${fontSize * 0.9}px`,
              borderRadius: 999,
              background: COLORS.teal,
              color: "rgba(255,255,255,1)",
              fontWeight: FONTS.displayWeight,
              fontStyle: "italic",
              textTransform: "uppercase",
              fontSize,
              lineHeight: 1,
              textAlign: "center",
              overflowWrap: "break-word",
              textShadow: "0 2px 10px rgba(0,0,0,0.35)",
              opacity: Math.min(1, captionIn),
              scale: String(captionIn),
            }}
          >
            {text}
          </div>
        </AbsoluteFill>
      ) : null}
    </AbsoluteFill>
  );
};

export default SplitSlideDuo;
